func TestLogRedaction(t *testing.T) {
	p := NewRedactionProcessor(RedactionOptions{Patterns: []*regexp.Regexp{regexp.MustCompile(`sk-[a-z0-9]+`)}})
	in := LogRecord{
		Body: "key sk-abc123 used",
		Attributes: map[string]AttrValue{
			"user":      "bob",
			"API_KEY":   "k",
			"nested":    map[string]any{"db_password": "p", "list": []any{"sk-zzz", map[string]any{"Authorization": "Bearer x"}, 3}},
			"plain_map": map[string]string{"session_token": "t"},
			"num":       5,
		},
		Resource: map[string]AttrValue{"token": "resource attributes are not redacted"},
	}
	out := p.Process(in)
	nested := out.Attributes["nested"].(map[string]any)
	list := nested["list"].([]any)
	if out.Body != "key [REDACTED] used" || out.Attributes["user"] != "bob" || out.Attributes["API_KEY"] != Redacted ||
		nested["db_password"] != Redacted || list[0] != Redacted || list[1].(map[string]any)["Authorization"] != Redacted ||
		list[2] != int64(3) || out.Attributes["plain_map"].(map[string]any)["session_token"] != Redacted || out.Attributes["num"] != int64(5) {
		t.Fatalf("redacted = %#v", out)
	}
	if in.Attributes["API_KEY"] != "k" || in.Attributes["nested"].(map[string]any)["db_password"] != "p" {
		t.Fatal("input mutated")
	}
	if out.Resource["token"] == Redacted {
		t.Fatal("resource redacted")
	}
	none := NewRedactionProcessor(RedactionOptions{Keys: []string{}})
	if got := none.Process(LogRecord{Attributes: map[string]AttrValue{"password": "x"}}); got.Attributes["password"] != "x" {
		t.Fatal("empty key list must disable key matching")
	}
	custom := NewRedactionProcessor(RedactionOptions{Keys: []string{"  PIN ", ""}})
	if got := custom.Process(LogRecord{Attributes: map[string]AttrValue{"user_pin": "1234"}}); got.Attributes["user_pin"] != Redacted {
		t.Fatalf("custom keys = %#v", got)
	}
	if len(DefaultRedactKeys) != 10 {
		t.Fatal("DefaultRedactKeys changed")
	}
}

