func equalAttr(a, b any) bool {
	al, aok := a.([]any)
	bl, bok := b.([]any)
	if aok && bok {
		if len(al) != len(bl) {
			return false
		}
		for i := range al {
			if al[i] != bl[i] {
				return false
			}
		}
		return true
	}
	return a == b
}

func TestLogSlogHandler(t *testing.T) {
	sink := &ltSink{}
	h := NewSlogHandler(sink, nil)
	logger := slog.New(h)
	ctx := trace.ContextWithSpanContext(context.Background(), ltSpanContext())
	logger.DebugContext(ctx, "hidden")
	if len(sink.records) != 0 {
		t.Fatal("debug passed the default level")
	}
	logger.With("svc", "a").WithGroup("req").With("id", 7).WithGroup("empty").InfoContext(ctx, "hello", "k", "v")
	r := sink.last(t)
	req, _ := r.Attributes["req"].(map[string]AttrValue)
	if r.Body != "hello" || r.Severity != SeverityInfo || r.Attributes["svc"] != "a" || req["id"] != int64(7) ||
		r.TraceID != "4bf92f3577b34da6a3ce929d0e0e4736" || r.Timestamp.IsZero() {
		t.Fatalf("record = %#v", r)
	}
	if req["empty"].(map[string]AttrValue)["k"] != "v" {
		t.Fatalf("record attrs belong to the innermost group: %#v", req)
	}
	logger.WithGroup("a").With(slog.Group("x")).Info("pruned")
	if _, ok := sink.last(t).Attributes["a"]; ok {
		t.Fatal("empty group kept")
	}
	logger.WithGroup("req").InfoContext(context.Background(), "inside", "k", "v")
	if r := sink.last(t); r.Attributes["req"].(map[string]AttrValue)["k"] != "v" {
		t.Fatalf("group attrs = %#v", r.Attributes)
	}

	if h.WithGroup("") != h || h.WithAttrs(nil) != h {
		t.Fatal("no-op WithGroup/WithAttrs should return the handler")
	}

	src := slog.New(NewSlogHandler(sink, &SlogHandlerOptions{Level: slog.LevelDebug, AddSource: true}))
	src.Debug("with source")
	r = sink.last(t)
	if r.Severity != SeverityDebug || !strings.HasSuffix(r.Attributes["code.file.path"].(string), "_test.go") ||
		r.Attributes["code.line.number"].(int64) <= 0 || r.Attributes["code.function.name"] == "" {
		t.Fatalf("source = %#v", r.Attributes)
	}
	var nilCtx context.Context
	if err := h.Handle(nilCtx, slog.NewRecord(time.Now(), slog.LevelWarn, "nil ctx", 0)); err != nil || sink.last(t).Severity != SeverityWarn {
		t.Fatal("nil ctx handle")
	}
	if !NewSlogHandler(sink, &SlogHandlerOptions{}).Enabled(context.Background(), slog.LevelInfo) {
		t.Fatal("default level from empty options")
	}
	for level, want := range map[slog.Level]Severity{-20: SeverityTrace, -8: SeverityTrace, -4: SeverityDebug, 0: SeverityInfo, 4: SeverityWarn, 8: SeverityError, 12: SeverityFatal, 100: 24} {
		if got := SeverityFromSlog(level); got != want {
			t.Errorf("SeverityFromSlog(%d) = %d, want %d", level, got, want)
		}
	}
}
